// Advanced Corner Accents Rendering Component
// This component renders corner accents with 10 styles and effects, plus symbol library support

import React from 'react';
import { getSymbolById } from '@/config/decorators/corner-symbols';

interface CornerAccentRendererProps {
  config: any;
  pillarColor: string;
}

/**
 * Calculate corner offset based on symbol type and size
 * to prevent cropping of large or rotated symbols
 */
const getCornerOffset = (style: string, size: number): number => {
  const baseOffset = 64;
  switch (style) {
    case 'diamond':
      // Diamond rotated 45°, diagonal = size × √2 ≈ size × 1.414
      // Extra space needed: (size × 0.414) / 2
      return baseOffset + (size * 0.4);
    case 'star':
    case 'arrow':
      // These symbols have protrusions that extend beyond the bounding box
      return baseOffset + (size * 0.25);
    case 'triangle':
      // Triangle extends beyond its size due to rotation
      return baseOffset + (size * 0.2);
    case 'circle':
    case 'cross':
    case 'wave':
      // These have some protrusion but less
      return baseOffset + (size * 0.15);
    case 'dot':
    case 'line':
      // Small symbols, minimal extra space
      return baseOffset + (size * 0.05);
    default:
      return baseOffset;
  }
};

export function CornerAccentRenderer({ config, pillarColor }: CornerAccentRendererProps) {
  if (!config.cornerAccents.enabled) return null;

  return (
    <>
      {['topLeft', 'topRight', 'bottomLeft', 'bottomRight'].map((corner) => {
        const cornerConfig = config.cornerAccents[corner as keyof typeof config.cornerAccents];
        if (!cornerConfig || typeof cornerConfig !== 'object' || !cornerConfig.enabled) return null;

        // Calculate dynamic offset based on symbol type and size
        const offset = getCornerOffset(cornerConfig.style || 'bracket', cornerConfig.size || 48);

        const positionStyles: Record<string, { top: string; left: string; right: string; bottom: string }> = {
          topLeft: { top: `${offset}px`, left: `${offset}px`, right: 'auto', bottom: 'auto' },
          topRight: { top: `${offset}px`, left: 'auto', right: `${offset}px`, bottom: 'auto' },
          bottomLeft: { top: 'auto', left: `${offset}px`, right: 'auto', bottom: `${offset}px` },
          bottomRight: { top: 'auto', left: 'auto', right: `${offset}px`, bottom: `${offset}px` },
        };

        const pos = positionStyles[corner];
        const rotation = cornerConfig.rotation || 0;
        const offsetX = cornerConfig.offset?.x || 0;
        const offsetY = cornerConfig.offset?.y || 0;
        const effects = cornerConfig.effects || {};
        const symbol = cornerConfig.symbolId ? getSymbolById(cornerConfig.symbolId) : null;

        return (
          <div
            key={corner}
            className="absolute z-20"
            style={{
              top: pos.top,
              left: pos.left,
              right: pos.right,
              bottom: pos.bottom,
              transform: `translate(${offsetX}px, ${offsetY}px) rotate(${rotation}deg)`,
            }}
          >
            {/* Symbol from Library - takes precedence over built-in styles */}
            {symbol && !cornerConfig.style && (
              <svg
                width={cornerConfig.size}
                height={cornerConfig.size}
                viewBox="0 0 40 40"
                fill="none"
                stroke={cornerConfig.color || pillarColor}
                strokeWidth={cornerConfig.thickness || 4}
                style={{
                  filter: effects.shadow
                    ? `drop-shadow(0 4px 12px ${(cornerConfig.color || pillarColor)}40)`
                    : effects.glow
                    ? `drop-shadow(0 0 8px ${cornerConfig.color || pillarColor})`
                    : effects.blur
                    ? 'blur(2px)'
                    : 'none',
                }}
              >
                <path d={symbol.path} />
              </svg>
            )}

            {/* Built-in Styles - only rendered if no symbolId is set */}
            {cornerConfig.style === 'bracket' && (
              <div
                style={{
                  width: `${cornerConfig.size}px`,
                  height: `${cornerConfig.size}px`,
                  borderTop: `${cornerConfig.thickness || 8}px solid ${cornerConfig.color || pillarColor}`,
                  borderLeft: corner === 'topLeft' || corner === 'bottomLeft'
                    ? `${cornerConfig.thickness || 8}px solid ${cornerConfig.color || pillarColor}`
                    : 'none',
                  borderRight: corner === 'topRight' || corner === 'bottomRight'
                    ? `${cornerConfig.thickness || 8}px solid ${cornerConfig.color || pillarColor}`
                    : 'none',
                  borderBottom: corner === 'bottomLeft' || corner === 'bottomRight'
                    ? `${cornerConfig.thickness || 8}px solid ${cornerConfig.color || pillarColor}`
                    : 'none',
                  boxShadow: effects.shadow
                    ? `0 4px 12px ${cornerConfig.color || pillarColor}40`
                    : 'none',
                  filter: effects.glow
                    ? `drop-shadow(0 0 8px ${cornerConfig.color || pillarColor})`
                    : effects.blur
                    ? 'blur(2px)'
                    : 'none',
                }}
              />
            )}

            {/* Line Style */}
            {cornerConfig.style === 'line' && (
              <div
                style={{
                  width: `${cornerConfig.size}px`,
                  height: `${cornerConfig.thickness || 8}px`,
                  backgroundColor: cornerConfig.color || pillarColor,
                  boxShadow: effects.shadow
                    ? `0 2px 8px ${cornerConfig.color || pillarColor}40`
                    : 'none',
                  filter: effects.glow
                    ? `drop-shadow(0 0 6px ${cornerConfig.color || pillarColor})`
                    : effects.blur
                    ? 'blur(2px)'
                    : 'none',
                }}
              />
            )}

            {/* Dot Style */}
            {cornerConfig.style === 'dot' && (
              <div
                style={{
                  width: `${cornerConfig.size * 0.4}px`,
                  height: `${cornerConfig.size * 0.4}px`,
                  borderRadius: '50%',
                  backgroundColor: cornerConfig.color || pillarColor,
                  boxShadow: effects.shadow
                    ? `0 2px 8px ${cornerConfig.color || pillarColor}40`
                    : 'none',
                  filter: effects.glow
                    ? `drop-shadow(0 0 6px ${cornerConfig.color || pillarColor})`
                    : effects.blur
                    ? 'blur(2px)'
                    : 'none',
                }}
              />
            )}

            {/* Triangle Style */}
            {cornerConfig.style === 'triangle' && (
              <div
                style={{
                  width: '0',
                  height: '0',
                  borderLeft: `${cornerConfig.size / 2}px solid transparent`,
                  borderTop: `${cornerConfig.size}px solid ${cornerConfig.color || pillarColor}`,
                  transform: corner === 'topRight'
                    ? 'rotate(-90deg)'   // Point up-left
                    : corner === 'bottomLeft'
                    ? 'rotate(90deg)'    // Point down-right
                    : corner === 'bottomRight'
                    ? 'rotate(180deg)'   // Point down-left
                    : 'rotate(0deg)',    // Point up-right (top-left)
                  filter: effects.glow
                    ? `drop-shadow(0 0 6px ${cornerConfig.color || pillarColor})`
                    : effects.blur
                    ? 'blur(2px)'
                    : 'none',
                }}
              />
            )}

            {/* Circle Style */}
            {cornerConfig.style === 'circle' && (
              <div
                style={{
                  width: `${cornerConfig.size}px`,
                  height: `${cornerConfig.size}px`,
                  borderRadius: '50%',
                  border: `${cornerConfig.thickness || 8}px solid ${cornerConfig.color || pillarColor}`,
                  boxShadow: effects.shadow
                    ? `0 4px 12px ${cornerConfig.color || pillarColor}40`
                    : 'none',
                  filter: effects.glow
                    ? `drop-shadow(0 0 8px ${cornerConfig.color || pillarColor})`
                    : effects.blur
                    ? 'blur(2px)'
                    : 'none',
                }}
              />
            )}

            {/* Cross Style */}
            {cornerConfig.style === 'cross' && (
              <div
                style={{
                  width: `${cornerConfig.size}px`,
                  height: `${cornerConfig.size}px`,
                  position: 'relative',
                }}
              >
                <div
                  style={{
                    position: 'absolute',
                    top: '50%',
                    left: 0,
                    right: 0,
                    height: `${cornerConfig.thickness || 8}px`,
                    backgroundColor: cornerConfig.color || pillarColor,
                    transform: 'translateY(-50%)',
                  }}
                />
                <div
                  style={{
                    position: 'absolute',
                    left: '50%',
                    top: 0,
                    bottom: 0,
                    width: `${cornerConfig.thickness || 8}px`,
                    backgroundColor: cornerConfig.color || pillarColor,
                    transform: 'translateX(-50%)',
                  }}
                />
              </div>
            )}

            {/* Star Style */}
            {cornerConfig.style === 'star' && (
              <svg
                width={cornerConfig.size}
                height={cornerConfig.size}
                viewBox="0 0 24 24"
                fill="none"
                stroke={cornerConfig.color || pillarColor}
                strokeWidth={cornerConfig.thickness || 8}
                style={{
                  filter: effects.glow
                    ? `drop-shadow(0 0 6px ${cornerConfig.color || pillarColor})`
                    : effects.blur
                    ? 'blur(2px)'
                    : 'none',
                }}
              >
                <polygon points="12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2" />
              </svg>
            )}

            {/* Diamond Style */}
            {cornerConfig.style === 'diamond' && (
              <div
                style={{
                  width: `${cornerConfig.size}px`,
                  height: `${cornerConfig.size}px`,
                  backgroundColor: cornerConfig.color || pillarColor,
                  transform: 'rotate(45deg)',
                  boxShadow: effects.shadow
                    ? `0 4px 12px ${cornerConfig.color || pillarColor}40`
                    : 'none',
                  filter: effects.glow
                    ? `drop-shadow(0 0 8px ${cornerConfig.color || pillarColor})`
                    : effects.blur
                    ? 'blur(2px)'
                    : 'none',
                }}
              />
            )}

            {/* Arrow Style */}
            {cornerConfig.style === 'arrow' && (
              <svg
                width={cornerConfig.size}
                height={cornerConfig.size}
                viewBox="0 0 24 24"
                fill="none"
                stroke={cornerConfig.color || pillarColor}
                strokeWidth={cornerConfig.thickness || 8}
                style={{
                  transform: corner === 'bottomLeft' || corner === 'bottomRight'
                    ? 'rotate(180deg)'
                    : 'rotate(0deg)',
                  filter: effects.glow
                    ? `drop-shadow(0 0 6px ${cornerConfig.color || pillarColor})`
                    : effects.blur
                    ? 'blur(2px)'
                    : 'none',
                }}
              >
                <path d="M5 12h14M12 5l7 7-7 7" />
              </svg>
            )}

            {/* Wave Style */}
            {cornerConfig.style === 'wave' && (
              <svg
                width={cornerConfig.size}
                height={cornerConfig.size / 2}
                viewBox="0 0 24 12"
                fill="none"
                stroke={cornerConfig.color || pillarColor}
                strokeWidth={cornerConfig.thickness || 8}
                style={{
                  filter: effects.glow
                    ? `drop-shadow(0 0 6px ${cornerConfig.color || pillarColor})`
                    : effects.blur
                    ? 'blur(2px)'
                    : 'none',
                }}
              >
                <path d="M2 6c2-2 4-2 6 0s4 2 6 0 4-2 6-0" />
              </svg>
            )}
</div>
        );
      })}
    </>
  );
}