/**
 * Masonry 3 Layout
 * 3 images in grid
 */
const Masonry3Layout: React.FC<{ config: ImageConfig; pillarColor?: string }> = ({ config, pillarColor }) => {
  const [imageStates, setImageStates] = useState<ImageState[]>([
    { isLoading: true, hasError: false, isLoaded: false },
    { isLoading: true, hasError: false, isLoaded: false },
    { isLoading: true, hasError: false, isLoaded: false },
  ]);

  const handleLoad = (index: number) => {
    setImageStates((prev) => {
      const newStates = [...prev];
      newStates[index] = { isLoading: false, hasError: false, isLoaded: true };
      return newStates;
    });
  };

  const handleError = (index: number) => {
    setImageStates((prev) => {
      const newStates = [...prev];
      newStates[index] = { isLoading: false, hasError: true, isLoaded: false };
      return newStates;
    });
  };

  // For masonry, we use the same image 3 times (in real implementation, would use multiple images)
  return (
    <div className="absolute inset-0 p-8">
      <div className="grid grid-cols-2 gap-4 h-full">
        <div className="relative overflow-hidden rounded-lg">
          <img
            src={imageStates[0].hasError ? DEFAULT_FALLBACK_IMAGE : config.imageUrl}
            alt=""
            className="absolute inset-0 w-full h-full object-cover"
            style={{
              objectFit: config.objectFit,
              filter: getFilterStyle(config.filters),
              opacity: config.opacity ?? 1,
              mixBlendMode: config.blendMode || 'normal',
            }}
            onLoad={() => handleLoad(0)}
            onError={() => handleError(0)}
          />
          {imageStates[0].isLoading && (
            <div className="absolute inset-0 flex items-center justify-center bg-gray-900/50">
              <div className="w-8 h-8 border-2 border-white border-t-transparent rounded-full animate-spin" />
            </div>
          )}
          {/* Caption */}
          {config.caption && config.captionPosition !== 'none' && (
            <div style={getCaptionStyle(config.captionPosition)}>
              <p className="text-xs text-white" style={{ textShadow: '0 2px 4px rgba(0,0,0,0.8)' }}>
                {config.caption}
              </p>
            </div>
          )}
        </div>
        <div className="flex flex-col gap-4">
          <div className="flex-1 relative overflow-hidden rounded-lg">
            <img
              src={imageStates[1].hasError ? DEFAULT_FALLBACK_IMAGE : config.imageUrl}
              alt=""
              className="absolute inset-0 w-full h-full object-cover"
              style={{
                objectFit: config.objectFit,
                filter: getFilterStyle(config.filters),
                opacity: config.opacity ?? 1,
                mixBlendMode: config.blendMode || 'normal',
              }}
              onLoad={() => handleLoad(1)}
              onError={() => handleError(1)}
            />
            {imageStates[1].isLoading && (
              <div className="absolute inset-0 flex items-center justify-center bg-gray-900/50">
                <div className="w-8 h-8 border-2 border-white border-t-transparent rounded-full animate-spin" />
              </div>
            )}
            {/* Caption */}
            {config.caption && config.captionPosition !== 'none' && (
              <div style={getCaptionStyle(config.captionPosition)}>
                <p className="text-xs text-white" style={{ textShadow: '0 2px 4px rgba(0,0,0,0.8)' }}>
                  {config.caption}
                </p>
              </div>
            )}
          </div>
          <div className="flex-1 relative overflow-hidden rounded-lg">
            <img
              src={imageStates[2].hasError ? DEFAULT_FALLBACK_IMAGE : config.imageUrl}
              alt=""
              className="absolute inset-0 w-full h-full object-cover"
              style={{
                objectFit: config.objectFit,
                filter: getFilterStyle(config.filters),
                opacity: config.opacity ?? 1,
                mixBlendMode: config.blendMode || 'normal',
              }}
              onLoad={() => handleLoad(2)}
              onError={() => handleError(2)}
            />
            {imageStates[2].isLoading && (
              <div className="absolute inset-0 flex items-center justify-center bg-gray-900/50">
                <div className="w-8 h-8 border-2 border-white border-t-transparent rounded-full animate-spin" />
              </div>
            )}
            {/* Caption */}
            {config.caption && config.captionPosition !== 'none' && (
              <div style={getCaptionStyle(config.captionPosition)}>
                <p className="text-xs text-white" style={{ textShadow: '0 2px 4px rgba(0,0,0,0.8)' }}>
                  {config.caption}
                </p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

/**
 * Main ImageRenderer Component
 *
 * Renders images based on the specified layout position.
 */
export const ImageRenderer: React.FC<ImageRendererProps> = ({ config, pillarColor, onError, onLoad }) => {
  const renderLayout = () => {
    switch (config.position) {
      case 'full-bleed':
        return <FullBleedLayout config={config} pillarColor={pillarColor} />;
      case 'half-left':
        return <HalfLeftLayout config={config} pillarColor={pillarColor} />;
      case 'half-right':
        return <HalfRightLayout config={config} pillarColor={pillarColor} />;
      case 'card':
        return <CardLayout config={config} pillarColor={pillarColor} />;
      case 'gradient-overlay':
        return <GradientOverlayLayout config={config} pillarColor={pillarColor} />;
      case 'frame':
        return <FrameLayout config={config} pillarColor={pillarColor} />;
      case 'polaroid':
        return <PolaroidLayout config={config} pillarColor={pillarColor} />;
      case 'diagonal-split':
        return <DiagonalSplitLayout config={config} pillarColor={pillarColor} />;
      case 'masonry-2':
        return <Masonry2Layout config={config} pillarColor={pillarColor} />;
      case 'masonry-3':
        return <Masonry3Layout config={config} pillarColor={pillarColor} />;
      default:
        return <FullBleedLayout config={config} pillarColor={pillarColor} />;
    }
  };

  return <>{renderLayout()}</>;
};

export default ImageRenderer;